async function s(r,n,o=[],t){try{const e=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:r,history:o.slice(-10),userId:n,tier:t?.tier||"free",memoryContext:t?.memoryContext||[],documentContext:t?.documentContext||"",systemPrompt:t?.systemPrompt})});if(!e.ok)throw new Error(`API error ${e.status}`);return(await e.json()).response||"No response received."}catch(e){return console.error("[sendChatMessage] Failed:",e),"I'm having trouble connecting right now. Please try again in a moment."}}export{s};
